def running_max(nums):
    out=[]; m=None
    for x in nums:
        m = x if m is None else max(m, x)
        out.append(m)
    return out

def is_balanced(s):
    d=0
    for c in s:
        if c=='(': d+=1
        elif c==')':
            d-=1
            if d<0: return False
    return d==0
